1	import { computed, inject, Injectable } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { NavigationEnd, Router } from '@angular/router';
4	import { filter, map } from 'rxjs';
5	import { ThemeService } from './theme/theme.service';
6	
7	export type NavIconName =
8	  | 'lucideLayoutDashboard'
9	  | 'lucideUsers'
10	  | 'lucideTarget'
11	  | 'lucideShieldAlert'
12	  | 'lucideUserPlus'
13	  | 'lucideSettings';
14	
15	export interface NavItem {
16	  readonly label: string;
17	  readonly path: string;
18	  readonly icon: NavIconName;
19	}
20	
21	// The six rail destinations. Hero detail is reached from the roster, not the rail.
22	const NAV_ITEMS: readonly NavItem[] = [
23	  { label: 'Dashboard', path: '/dashboard', icon: 'lucideLayoutDashboard' },
24	  { label: 'Roster', path: '/heroes', icon: 'lucideUsers' },
25	  { label: 'Missions', path: '/missions', icon: 'lucideTarget' },
26	  { label: 'Threats', path: '/threats', icon: 'lucideShieldAlert' },
27	  { label: 'Recruit', path: '/recruit', icon: 'lucideUserPlus' },
28	  { label: 'Settings', path: '/settings', icon: 'lucideSettings' },
29	];
30	
31	const SECTION_LABELS: Readonly<Record<string, string>> = {
32	  dashboard: 'Dashboard',
33	  heroes: 'Roster',
34	  detail: 'Hero detail',
35	  missions: 'Missions',
36	  threats: 'Threats',
37	  recruit: 'Recruit',
38	  settings: 'Settings',
39	};
40	
41	@Injectable()
42	export class AppViewModel {
43	  private readonly _router = inject(Router);
44	  private readonly _theme = inject(ThemeService);
45	
46	  private readonly _url = toSignal(
47	    this._router.events.pipe(
48	      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
49	      map((event) => event.urlAfterRedirects),
50	    ),
51	    { initialValue: this._router.url },
52	  );
53	
54	  public readonly navItems = NAV_ITEMS;
55	  public readonly isDark = this._theme.isDark;
56	
57	  public readonly themeLabel = computed(() =>
58	    this._theme.isDark() ? 'Switch to light theme' : 'Switch to dark theme',
59	  );
60	
61	  // Breadcrumb trail for the current route. Unknown sections fall back to the brand alone.
